const events = $input.all().map(i => i.json).filter(e => e.id);

if (!events || events.length === 0) {
  return [{ json: {
    resume: 'Aucun événement détecté cette semaine.',
    nb_total: 0,
    nb_alertes: 0,
    jours_data: '{}',
    score_moyen: '--',
    premiere: '--',
    derniere: '--'
  }}];
}

// --- STATS GLOBALES ---
const nb_total = events.length;
let nb_alertes = 0;
let total_score = 0;
let nb_score = 0;

// --- PAR JOUR ---
const jours = {};
const jours_noms = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];

for (const evt of events) {
  const date = new Date(evt.start_time * 1000);
  const cle = date.toLocaleDateString('fr-FR');
  const jour_nom = jours_noms[date.getDay()];

  if (!jours[cle]) jours[cle] = { nom: jour_nom, date: cle, nb: 0, alertes: 0, scores: [], premiere: null, derniere: null };

  jours[cle].nb++;
  if (evt.data && evt.data.max_severity === 'alert') { jours[cle].alertes++; nb_alertes++; }
  if (evt.data && evt.data.top_score) {
    jours[cle].scores.push(evt.data.top_score * 100);
    total_score += evt.data.top_score * 100;
    nb_score++;
  }
  if (!jours[cle].premiere || evt.start_time < jours[cle].premiere) jours[cle].premiere = evt.start_time;
  if (!jours[cle].derniere || evt.start_time > jours[cle].derniere) jours[cle].derniere = evt.start_time;
}

const score_moyen = nb_score > 0 ? Math.round(total_score / nb_score) + '%' : '--';

// --- RÉSUMÉ TEXTE PAR JOUR ---
const lignes_jours = Object.values(jours).sort((a,b) => {
  const da = a.date.split('/').reverse().join('-');
  const db = b.date.split('/').reverse().join('-');
  return da.localeCompare(db);
}).map(j => {
  const score_j = j.scores.length > 0 ? Math.round(j.scores.reduce((a,b)=>a+b,0)/j.scores.length) + '%' : '--';
  const premiere_h = j.premiere ? new Date(j.premiere * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'}) : '--';
  const derniere_h = j.derniere ? new Date(j.derniere * 1000).toLocaleTimeString('fr-FR', {hour:'2-digit', minute:'2-digit'}) : '--';
  return `${j.nom} ${j.date} : ${j.nb} détection(s), ${j.alertes} alerte(s), lever ~${premiere_h}, coucher ~${derniere_h}, score moyen ${score_j}`;
}).join('\n');

// --- SEMAINE ---
const debut_semaine = new Date(Math.min(...events.map(e => e.start_time)) * 1000).toLocaleDateString('fr-FR');
const fin_semaine = new Date(Math.max(...events.map(e => e.start_time)) * 1000).toLocaleDateString('fr-FR');

const resume = `Rapport hebdomadaire du ${debut_semaine} au ${fin_semaine}\n\nSTATISTIQUES GLOBALES:\n- Total détections : ${nb_total}\n- Total alertes : ${nb_alertes}\n- Score moyen IA : ${score_moyen}\n- Nombre de jours avec activité : ${Object.keys(jours).length}\n\nDÉTAIL PAR JOUR:\n${lignes_jours}`;

return [{ json: { resume, nb_total, nb_alertes, score_moyen, debut_semaine, fin_semaine, nb_jours: Object.keys(jours).length } }];

const raw = $input.item.json.response || 'Erreur génération rapport.';
const rapport_final = raw.replace(/\\n/g, '\n').trim();

const extraire = (texte, debut, fin) => {
  if (!texte.includes(debut)) return 'Non disponible.';
  const apres = texte.split(debut)[1];
  if (!fin || !apres.includes(fin)) return apres.trim();
  return apres.split(fin)[0].trim();
};

const bilan = extraire(rapport_final, 'BILAN SEMAINE', 'JOURS NOTABLES').replace(/^:\s*/, '');
const jours_notables = extraire(rapport_final, 'JOURS NOTABLES', 'TENDANCES').replace(/^:\s*/, '');
const tendances = extraire(rapport_final, 'TENDANCES', 'RECOMMANDATIONS').replace(/^:\s*/, '');
const recommandations = extraire(rapport_final, 'RECOMMANDATIONS', null).replace(/^:\s*/, '');

return [{ json: { rapport_final, bilan, jours_notables, tendances, recommandations } }];

const rapport = $('Code — Extrait rapport').first().json;
const salonBin  = $('HTTP — Photo Salon Hebdo').first().binary?.photo_salon  ?? null;
const entreeBin = $('HTTP — Photo Entrée Hebdo').first().binary?.photo_entree ?? null;
return [{
  json: { ...rapport, nb_photos: (salonBin ? 1 : 0) + (entreeBin ? 1 : 0) },
  binary: {
    ...(salonBin  ? { photo_salon:  salonBin  } : {}),
    ...(entreeBin ? { photo_entree: entreeBin } : {})
  }
}];
